<?php if($kind==='leave'||$kind==='leave_policies'): ?><section class="card"><h2><?= e(t('Available leave')) ?></h2><?php foreach(EmployeeService::rows('leave_policies')as $p):$policy=$p['fields'];$used=0;foreach(EmployeeService::rows('leave')as $leave)if($leave['fields']['policy']===$p['id']&&$leave['fields']['state']==='approved')$used+=$leave['fields']['days']; ?><p><?= e($policy['type']) ?> <?= e($policy['year']) ?> · <?= e($policy['opening_days']+$policy['accrued_days']+$policy['carry_over_days']-$used) ?> <?= e(t('days available ·')) ?> <?= e($used) ?> <?= e(t('approved.')) ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if($kind==='blockers'): ?><section class="card"><h2><?= e(t('Stand-up ·')) ?> <?= e(ui_date('Y-m-d')) ?></h2><h3><?= e(t('Completed yesterday')) ?></h3><ul><?php foreach(Db::all("SELECT title FROM tasks WHERE status='done' AND substr(completed_at,1,10)=?",[ui_date('Y-m-d',strtotime('-1 day'))])as $task): ?><li><?= e($task['title']) ?></li><?php endforeach; ?></ul><h3><?= e(t('Today')) ?></h3><ul><?php foreach(Db::all("SELECT title FROM tasks WHERE status='open' AND due=?",[ui_date('Y-m-d')])as $task): ?><li><?= e($task['title']) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
<?php if($kind==='offers'): ?><section class="card"><h2><?= e(t('Offer comparison')) ?></h2><p><?= e(t('Entered net pay less commuting costs. Benefits remain descriptive and are not assigned invented monetary values.')) ?></p><div class="table-wrap"><table><tr><th><?= e(t('Company')) ?></th><th><?= e(t('After commute / month')) ?></th><th><?= e(t('Weekly hours')) ?></th><th><?= e(t('Notice days')) ?></th></tr><?php foreach(EmployeeService::rows('offers')as $offer):$v=$offer['fields']; ?><tr><td><?= e($v['company']) ?></td><td><?= money($v['monthly_net']-$v['monthly_commute']) ?></td><td><?= e($v['weekly_hours']) ?></td><td><?= e($v['notice_days']) ?></td></tr><?php endforeach; ?></table></div></section><?php endif; ?>
